# Questions for L12–L18
from st import *

# ---------- L12 sampling ----------
Q("L12", "From a list of 5,000 voters, a random number between 1 and 10 is chosen and then every 10th voter is taken. This is:", ["systematic sampling", "simple random sampling", "cluster sampling", "stratified sampling"], "A random start followed by a fixed interval k = N/n is systematic sampling.", hy=True)
Q("L12", "A few villages are chosen at random and every household in the chosen villages is surveyed. This is:", ["cluster sampling", "stratified sampling", "systematic sampling", "quota sampling"], "Whole groups (clusters) are selected and fully enumerated.", hy=True)
Q("L12", "A population is divided into homogeneous groups and a random sample is drawn from every group. This is:", ["stratified sampling", "cluster sampling", "multistage sampling", "purposive sampling"], "Homogeneous strata, with a sample from each stratum, is stratified sampling.")
Q("L12", "A survey selects states, then districts within the selected states, then villages, and finally households. This is:", ["multistage sampling", "multiphase sampling", "cluster sampling", "systematic sampling"], "Selection in successive stages of ever smaller units is multistage sampling.")
Q("L12", "An interviewer must contact 30 men and 20 women but may choose whom to interview. This is:", ["quota sampling", "stratified random sampling", "systematic sampling", "simple random sampling"], "Fixed quotas filled at the interviewer’s choice — a non-probability method.")
Q("L12", "An investigator deliberately selects units he considers typical of the population. This is:", ["purposive (judgement) sampling", "simple random sampling", "cluster sampling", "systematic sampling"], "Selection by judgement is purposive sampling; personal bias can enter.")
Q("L12", "How many different samples of size 3 can be drawn without replacement from a population of 8 units?", ["@", "512", "336", "24"], "C(8, 3) = 56. (512 = 8³ counts ordered samples with replacement; 336 counts ordered samples without replacement.)", C(8, 3))
Q("L12", "How many ordered samples of size 2 can be drawn with replacement from a population of 6 units?", ["@", "15", "30", "12"], "6² = 36.", 6 ** 2)
Q("L12", "In simple random sampling without replacement of 10 units from 50, the probability that a particular unit is included is:", ["@", "1/50", "1/10", "10/49"], "n/N = 10/50 = 1/5.", Fr(10, 50))
Q("L12", "σ = 20 and n = 100. The standard error of the sample mean is:", ["@", "0.2", "20", "4"], "σ/√n = 20/10 = 2.", fmt(F(20, 10)), hy=True)
Q("L12", "The population proportion is 0.4 and n = 96. The standard error of the sample proportion is:", ["@", "0.0025", "0.24", "0.004"], "√(PQ/n) = √(0.24/96) = √0.0025 = 0.05.", fmt(math.sqrt(0.4 * 0.6 / 96)))
Q("L12", "To halve the standard error of the mean, the sample size must be:", ["multiplied by 4", "doubled", "halved", "multiplied by √2"], "SE ∝ 1/√n, so n must become 4n.")
Q("L12", "σ = 10, n = 25 drawn without replacement from N = 101. The standard error of the mean is:", ["@", "2", "1.6", "0.4"], "(10/5) × √[(101 − 25)/(101 − 1)] = 2 × √0.76 ≈ 1.74.", fmt(2 * math.sqrt(76 / 100)))
_Nh = [600, 300, 100]
Q("L12", "Strata have 600, 300 and 100 units. With proportional allocation, how many of a sample of 50 come from the second stratum?", ["@", "30", "5", "16"], "nₕ = 50 × 300/1000 = 15.", 50 * _Nh[1] // sum(_Nh))
_w = [400 * 5, 600 * 10]
Q("L12", "Stratum 1 has N₁ = 400 and S₁ = 5; stratum 2 has N₂ = 600 and S₂ = 10. Under Neyman allocation of n = 80, the sample from stratum 1 is:", ["@", "32", "40", "60"], "nₕ ∝ NₕSₕ: 2000 and 6000 → 80 × 2000/8000 = 20. (32 is proportional allocation.)", 80 * _w[0] // sum(_w))
Q("L12", "σ = 15. The sample size needed to estimate the mean within ±3 with 95% confidence is:", ["@", "96", "25", "75"], "n = (1.96 × 15/3)² = 9.8² = 96.04 → round up to 97.", math.ceil((1.96 * 15 / 3) ** 2))
Q("L12", "Nothing is known about a proportion. The sample size needed to estimate it within ±0.05 with 95% confidence is:", ["@", "384", "100", "196"], "n = 1.96² × 0.25/0.05² = 384.16 → 385. Use P = 0.5, the worst case.", math.ceil(1.96 ** 2 * 0.25 / 0.05 ** 2))
Q("L12", "Which statement about non-sampling errors is correct?", ["They occur in a census as well as in a sample survey", "They disappear in a census", "They always fall as the sample size rises", "They can be found exactly from the sample"], "Measurement, response and processing errors occur in any enquiry, and are often larger in a census.")
Q("L12", "Sampling error generally decreases when:", ["the sample size increases", "the population size increases", "non-response increases", "a non-probability method is used"], "Sampling error ∝ 1/√n.")
Q("L12", "Independent samples: σ₁ = 6, n₁ = 36 and σ₂ = 8, n₂ = 64. The standard error of the difference of the sample means is:", ["@", "2", "0.25", "14"], "√(36/36 + 64/64) = √2 ≈ 1.41.", fmt(math.sqrt(36 / 36 + 64 / 64)))
Q("L12", "For systematic sampling of 60 units from a population of 1,200, the sampling interval is:", ["@", "60", "12", "1140"], "k = N/n = 1200/60 = 20.", 1200 // 60)
Q("L12", "The list of all units from which a sample is drawn is called the:", ["sampling frame", "sampling unit", "sampling distribution", "strata"], "The frame is the list; a sampling unit is one element of it.")

# ---------- L13 estimation ----------
Q("L13", "Which of the following is an unbiased estimator of the population variance σ²?", ["Σ(x − x̄)²/(n − 1)", "Σ(x − x̄)²/n", "Σ(x − x̄)²/(n + 1)", "Σx²/n"], "E[Σ(x − x̄)²] = (n − 1)σ², so dividing by n − 1 removes the bias.", hy=True)
Q("L13", "In 60 independent trials there are 18 successes. The maximum likelihood estimate of p is:", ["@", "0.18", "0.6", "0.7"], "p̂ = x/n = 18/60 = 0.3.", fmt(F(18, 60)))
_d = [0, 2, 1, 3, 2, 4]
Q("L13", "A Poisson sample gives 0, 2, 1, 3, 2, 4. The maximum likelihood estimate of the mean is:", ["@", "2.4", "1.67", "4"], "m̂ = x̄ = 12/6 = 2.", fmt(mean(_d)), hy=True)
Q("L13", "A sample from an exponential distribution f(x) = λe^(−λx) has mean 4. The ML estimate of λ is:", ["@", "4", "16", "0.0625"], "λ̂ = 1/x̄ = 1/4 = 0.25.", fmt(F(1, 4)))
Q("L13", "A sample from a uniform distribution on (0, θ) has mean 7. The method-of-moments estimate of θ is:", ["@", "7", "3.5", "49"], "E(X) = θ/2 → θ/2 = x̄ → θ̂ = 2 × 7 = 14.", 2 * 7)
_d = [3, 9, 5, 7]
Q("L13", "A sample 3, 9, 5, 7 comes from a uniform distribution on (0, θ). The maximum likelihood estimate of θ is:", ["@", "12", "6", "24"], "The likelihood 1/θⁿ is largest for the smallest θ that still covers all values: the largest observation, 9. (12 is the moments estimate 2x̄.)", max(_d))
_d = [2, 4, 6]
Q("L13", "A normal sample gives 2, 4, 6. The maximum likelihood estimate of σ² is:", ["@", "4", "2", "1.63"], "σ̂² = Σ(x − x̄)²/n = 8/3 ≈ 2.67. (4 is the unbiased s² with n − 1.)", fmt(pvar(_d)))
Q("L13", "x̄ = 80, σ = 12, n = 36. The 95% confidence interval for μ is:", ["@", "78.04 to 81.96", "74.84 to 85.16", "76.71 to 83.29"], "80 ± 1.96 × 12/6 = 80 ± 3.92.", "%s to %s" % (fmt(80 - 1.96 * 2), fmt(80 + 1.96 * 2)), hy=True)
Q("L13", "σ = 10 and n = 100. The width of the 99% confidence interval for μ is:", ["@", "3.92", "2.58", "10.32"], "2 × 2.58 × 10/10 = 5.16.", fmt(2 * 2.58 * 1))
Q("L13", "In a sample of 600, 40% favour a policy. The margin of error of a 95% confidence interval for the proportion is about:", ["@", "0.02", "0.0784", "0.4"], "SE = √(0.4 × 0.6/600) = 0.02; margin = 1.96 × 0.02 ≈ 0.039.", fmt(1.96 * math.sqrt(0.24 / 600), 3))
Q("L13", "If the sample size is made four times as large, the width of a confidence interval for the mean becomes:", ["half", "one-fourth", "double", "unchanged"], "Width ∝ 1/√n = 1/√4 = 1/2.")
Q("L13", "An estimator Tₙ is consistent for θ if:", ["Tₙ approaches θ in probability as n increases", "E(Tₙ) = θ for every n", "it has the smallest variance", "it uses all the sample observations"], "Consistency is a large-sample property: the estimator homes in on θ.")
Q("L13", "For a normal population, the more efficient estimator of μ is:", ["the sample mean", "the sample median", "the sample mode", "the mid-range of the sample"], "The median’s variance is about π/2 times that of the mean (efficiency ≈ 0.64).")
Q("L13", "For a random sample from a Poisson distribution, a sufficient statistic for the mean is:", ["Σxᵢ", "the largest observation", "x₁", "the sample median"], "The likelihood depends on the data only through Σxᵢ (factorisation theorem).")
Q("L13", "The method of maximum likelihood was developed by:", ["R. A. Fisher", "Karl Pearson", "A. A. Markov", "Jerzy Neyman"], "Fisher introduced ML in the 1920s; Karl Pearson gave the method of moments.")
Q("L13", "If θ̂ is the maximum likelihood estimator of θ, then the MLE of g(θ) is g(θ̂). This is the:", ["invariance property", "unbiasedness property", "sufficiency property", "Cramér–Rao bound"], "MLEs are invariant under functions of the parameter.")
Q("L13", "The Cramér–Rao inequality gives:", ["a lower bound for the variance of an unbiased estimator", "an upper bound for the bias of an estimator", "the sample size for a given precision", "the critical value of a test"], "No unbiased estimator (under regularity conditions) can have variance below this bound.")
Q("L13", "For a sample of 5 from a population with variance 10, E[Σ(x − x̄)²/n] is:", ["@", "10", "12.5", "2"], "E = (n − 1)σ²/n = 4 × 10/5 = 8 — the divisor-n variance is biased downwards.", fmt(F(4 * 10, 5)))
Q("L13", "Two unbiased estimators of θ have variances 4 and 5. The efficiency of the second relative to the first is:", ["@", "1.25", "0.2", "0.45"], "Efficiency = Var(T₁)/Var(T₂) = 4/5 = 0.8.", fmt(F(4, 5)))
Q("L13", "A sample of 9 has x̄ = 50 and s = 6 (divisor n − 1). With t₀.₀₂₅ at 8 df = 2.306, the upper 95% confidence limit for μ is:", ["@", "53.92", "63.84", "51.54"], "50 + 2.306 × 6/3 = 50 + 4.612 = 54.61.", fmt(50 + 2.306 * 2))

# ---------- L14 Z and t tests ----------
Q("L14", "A Type II error is committed when:", ["H₀ is accepted although it is false", "H₀ is rejected although it is true", "H₀ is rejected and it is false", "H₀ is accepted and it is true"], "Type I: reject a true H₀; Type II: accept a false H₀.", hy=True)
Q("L14", "The probability of a Type II error is 0.2. The power of the test is:", ["@", "0.2", "0.95", "0.05"], "Power = 1 − β = 0.8.", fmt(1 - F(2, 10)))
Q("L14", "The critical value of Z for a two-tailed test at the 1% level is:", ["2.58", "2.33", "1.96", "1.645"], "Each tail holds 0.5%: z = 2.58 (2.33 is the one-tailed 1% value).", hy=True)
assert fmt(N01.inv_cdf(0.995)) == "2.58" and fmt(N01.inv_cdf(0.99)) == "2.33"
Q("L14", "The critical value of Z for a right-tailed test at the 5% level is:", ["1.645", "1.96", "2.33", "1.28"], "The whole 5% is in one tail: z = 1.645.")
assert fmt(N01.inv_cdf(0.95), 3) == "1.645"
Q("L14", "H₀: μ = 50. A sample of 100 has x̄ = 52; σ = 10. The value of the Z statistic is:", ["@", "0.2", "20", "0.02"], "Z = (52 − 50)/(10/√100) = 2/1 = 2.", fmt(F(52 - 50, 1)))
Q("L14", "In 100 trials there are 60 successes. To test H₀: P = 0.5, the Z statistic is:", ["@", "1", "0.2", "2.04"], "Z = (0.6 − 0.5)/√(0.5 × 0.5/100) = 0.1/0.05 = 2. Using the sample p in the SE gives 2.04 — wrong under H₀.", fmt((0.6 - 0.5) / math.sqrt(0.25 / 100)))
Q("L14", "x̄₁ = 68, x̄₂ = 65; σ₁ = 10, σ₂ = 5; n₁ = n₂ = 50. The Z statistic for the difference of means is about:", ["@", "1.34", "2.12", "0.6"], "SE = √(100/50 + 25/50) = √2.5 ≈ 1.58; Z = 3/1.58 ≈ 1.90.", fmt(3 / math.sqrt(2.5)))
Q("L14", "The degrees of freedom for a one-sample t test with n = 15 are:", ["@", "15", "13", "16"], "n − 1 = 14.", 15 - 1)
Q("L14", "The degrees of freedom for a two-sample t test with n₁ = 10 and n₂ = 12 are:", ["@", "21", "22", "11"], "n₁ + n₂ − 2 = 20.", 10 + 12 - 2, hy=True)
Q("L14", "A paired t test is applied to 12 pairs of observations. The degrees of freedom are:", ["@", "22", "12", "10"], "Pairs give one difference each: n − 1 = 11.", 12 - 1)
Q("L14", "r = 0.6 from n = 18 pairs. The t statistic for testing ρ = 0 is:", ["@", "2.4", "3.6", "2.25"], "t = r√(n − 2)/√(1 − r²) = 0.6 × 4/0.8 = 3, with 16 df.", fmt(0.6 * 4 / 0.8))
Q("L14", "A sample of 9 has x̄ = 54 and s = 6 (divisor n − 1). For H₀: μ = 50, the t statistic is:", ["@", "0.67", "6", "1.33"], "t = (54 − 50)/(6/√9) = 4/2 = 2, with 8 df.", fmt(F(4, 2)))
Q("L14", "The variance of Student’s t distribution with 10 degrees of freedom is:", ["@", "1", "10", "0.8"], "ν/(ν − 2) = 10/8 = 1.25.", fmt(F(10, 8)))
Q("L14", "As the degrees of freedom increase, the t distribution tends to the:", ["standard normal distribution", "χ² distribution", "F distribution", "uniform distribution"], "Its tails thin out and its variance ν/(ν − 2) tends to 1.")
Q("L14", "A test gives a p-value of 0.03. At the 5% level of significance, H₀ is:", ["rejected", "accepted", "neither rejected nor accepted", "rejected only at the 1% level"], "Reject when the p-value is below α: 0.03 < 0.05. (At 1% it would not be rejected.)")
Q("L14", "For a fixed sample size, reducing α from 5% to 1% will:", ["increase β (the Type II error)", "decrease β", "increase the power", "leave β unchanged"], "A smaller critical region makes it harder to reject a false H₀ as well.")
Q("L14", "H₀: μ = 50 against H₁: μ > 50 calls for:", ["a right-tailed test", "a left-tailed test", "a two-tailed test", "no test at all"], "The critical region lies where H₁ points: the right tail.")
Q("L14", "The most powerful test for a simple null against a simple alternative is given by the:", ["Neyman–Pearson lemma", "central limit theorem", "Cramér–Rao inequality", "Chebyshev inequality"], "The lemma shows that the likelihood-ratio critical region is most powerful.")
_ph = F(30 + 20, 200)
_z = float(F(3, 10) - F(2, 10)) / math.sqrt(float(_ph * (1 - _ph) * (F(1, 100) + F(1, 100))))
Q("L14", "Two samples of 100 have proportions 0.3 and 0.2. Using the pooled proportion, the Z statistic for their difference is about:", ["@", "1.77", "2", "0.06"], "p̂ = 0.25; SE = √(0.25 × 0.75 × 0.02) ≈ 0.0612; Z = 0.1/0.0612 ≈ 1.63.", fmt(_z))
Q("L14", "The t distribution was introduced by:", ["W. S. Gosset (‘Student’)", "R. A. Fisher", "Karl Pearson", "Jerzy Neyman"], "Gosset published it under the pen name ‘Student’ in 1908.")

# ---------- L15 chi-square and F ----------
Q("L15", "A die is tested for fairness with a χ² goodness-of-fit test using 6 classes. The degrees of freedom are:", ["@", "6", "4", "1"], "k − 1 = 5 (no parameter estimated).", 6 - 1)
Q("L15", "A Poisson distribution is fitted with its mean estimated from the data; after pooling there are 7 classes. The df for the χ² test are:", ["@", "6", "4", "7"], "k − 1 − 1 = 5 (one parameter estimated).", 7 - 1 - 1, hy=True)
Q("L15", "A normal distribution is fitted (μ and σ estimated) to data in 10 classes. The df for the χ² test are:", ["@", "9", "8", "10"], "k − 1 − 2 = 7.", 10 - 1 - 2)
Q("L15", "The degrees of freedom for a χ² test of independence in a 4 × 5 contingency table are:", ["@", "20", "19", "9"], "(4 − 1)(5 − 1) = 12.", (4 - 1) * (5 - 1), hy=True)
Q("L15", "In a contingency table with N = 200, a cell’s row total is 60 and its column total is 50. Its expected frequency under independence is:", ["@", "110", "30", "55"], "E = 60 × 50/200 = 15.", fmt(F(60 * 50, 200)))
_O, _E = [30, 50, 20], [25, 50, 25]
Q("L15", "Observed frequencies 30, 50, 20 and expected frequencies 25, 50, 25. The value of χ² is:", ["@", "50", "10", "0"], "(25 + 0 + 25)/25 = 1 + 0 + 1 = 2.", fmt(sum(F((o - e) ** 2, e) for o, e in zip(_O, _E))))
Q("L15", "A coin tossed 100 times shows 60 heads. The χ² statistic for fairness is:", ["@", "2", "20", "0.2"], "E = 50 each: (100 + 100)/50 = 4.", fmt(F(10 ** 2, 50) * 2), hy=True)
_a, _b, _c, _d = 20, 30, 30, 20
Q("L15", "A 2 × 2 table has a = 20, b = 30, c = 30, d = 20. The value of χ² (without Yates’ correction) is:", ["@", "2", "1", "16"], "N(ad − bc)²/[(a + b)(c + d)(a + c)(b + d)] = 100 × 500²/50⁴ = 4.", fmt(F(100 * (_a * _d - _b * _c) ** 2, 50 ** 4)))
Q("L15", "The mean and variance of a χ² distribution with 8 degrees of freedom are:", ["8 and 16", "8 and 8", "16 and 8", "4 and 8"], "Mean ν = 8, variance 2ν = 16.")
Q("L15", "A sample of 11 has s² = 20 (divisor n − 1). For H₀: σ² = 10, the χ² statistic is:", ["@", "22", "2", "10"], "χ² = (n − 1)s²/σ₀² = 10 × 20/10 = 20, with 10 df.", F(10 * 20, 10))
Q("L15", "Two samples give unbiased variance estimates 18 and 12. The F ratio is:", ["@", "0.67", "6", "1.22"], "Larger over smaller: 18/12 = 1.5.", fmt(F(18, 12)))
Q("L15", "For an F test comparing variances of samples of sizes 9 and 13 (the first having the larger variance), the degrees of freedom are:", ["(8, 12)", "(9, 13)", "(12, 8)", "(20, 1)"], "(n₁ − 1, n₂ − 1) = (8, 12), with the numerator sample first.")
Q("L15", "F₀.₀₅(10, 5) = 4.74. The value of F₀.₉₅(5, 10) is about:", ["@", "4.74", "0.95", "2.37"], "F₁₋α(ν₁, ν₂) = 1/Fα(ν₂, ν₁) = 1/4.74 ≈ 0.21.", fmt(1 / 4.74))
Q("L15", "A t statistic with ν df has the value 2.5. Its square follows F with (1, ν) df and equals:", ["@", "5", "1.58", "2.5"], "t² = 6.25.", fmt(F(25, 10) ** 2))
Q("L15", "A χ² variable takes values in the range:", ["0 to ∞", "−∞ to ∞", "0 to 1", "−1 to 1"], "It is a sum of squares, so it is never negative.")
Q("L15", "Yates’ correction for continuity is applied in:", ["a 2 × 2 contingency table with small expected frequencies", "any F test", "a large-sample Z test for means", "ANOVA"], "It subtracts N/2 from |ad − bc| to offset the use of a continuous χ² for discrete counts.")
Q("L15", "In a χ² goodness-of-fit test, classes are pooled when:", ["an expected frequency is less than 5", "an observed frequency is 0", "the χ² value is too large", "the df exceed 30"], "Small expected frequencies make the χ² approximation unreliable.")
Q("L15", "The χ² test of goodness of fit is applied to:", ["observed and expected frequencies", "percentages", "sample means", "correlation coefficients"], "It compares counts; percentages must be turned back into frequencies.")
Q("L15", "The mean of an F distribution with (5, 10) degrees of freedom is:", ["@", "2", "0.5", "1"], "ν₂/(ν₂ − 2) = 10/8 = 1.25; it does not depend on ν₁.", fmt(F(10, 8)))
Q("L15", "If X ~ χ²(3) and Y ~ χ²(5) are independent, X + Y follows:", ["χ² with 8 df", "χ² with 15 df", "F with (3, 5) df", "t with 8 df"], "The χ² distribution is additive in its degrees of freedom.")

# ---------- L16 ANOVA ----------
Q("L16", "In one-way ANOVA with 24 observations, the total degrees of freedom are:", ["@", "24", "22", "20"], "N − 1 = 23.", 24 - 1)
Q("L16", "In one-way ANOVA with 4 treatments and 24 observations, the error degrees of freedom are:", ["@", "23", "3", "21"], "N − k = 24 − 4 = 20.", 24 - 4, hy=True)
Q("L16", "One-way ANOVA: 4 treatments, 24 observations, SST = 90 and SSE = 100. The F ratio is:", ["@", "0.9", "4.5", "1.11"], "MST = 90/3 = 30; MSE = 100/20 = 5; F = 30/5 = 6.", fmt(F(90, 3) / F(100, 20)), hy=True)
Q("L16", "The grand total of 20 observations is 120. The correction factor is:", ["@", "120", "6", "14400"], "CF = G²/N = 14400/20 = 720.", 120 ** 2 // 20)
Q("L16", "ΣΣx² = 800 and the correction factor is 720. The total sum of squares is:", ["@", "1520", "720", "800"], "TSS = 800 − 720 = 80.", 800 - 720)
_T = [30, 40, 50]
Q("L16", "Three treatments with 5 observations each have totals 30, 40 and 50. The treatment sum of squares is:", ["@", "1000", "960", "20"], "G = 120, N = 15, CF = 960; Σ(T²/n) = 5000/5 = 1000; SST = 1000 − 960 = 40.", F(sum(t * t for t in _T), 5) - F(120 ** 2, 15))
Q("L16", "In a two-way ANOVA with 5 rows and 4 columns (one observation per cell), the error degrees of freedom are:", ["@", "19", "7", "20"], "(r − 1)(c − 1) = 4 × 3 = 12.", (5 - 1) * (4 - 1), hy=True)
Q("L16", "In a two-way ANOVA with 5 rows and 4 columns (one observation per cell), the total degrees of freedom are:", ["@", "20", "12", "7"], "rc − 1 = 20 − 1 = 19.", 5 * 4 - 1)
Q("L16", "In a two-way ANOVA with 3 rows, 4 columns and 3 observations per cell, the error degrees of freedom are:", ["@", "6", "35", "12"], "rc(m − 1) = 12 × 2 = 24. (6 is the interaction df.)", 3 * 4 * (3 - 1))
Q("L16", "In a two-way ANOVA with 3 rows, 4 columns and 2 observations per cell, the interaction degrees of freedom are:", ["@", "12", "11", "5"], "(r − 1)(c − 1) = 2 × 3 = 6.", (3 - 1) * (4 - 1))
Q("L16", "Which of these is NOT an assumption of ANOVA?", ["All groups must have equal sample sizes", "The populations are normal", "The populations have equal variances", "The observations are independent"], "One-way ANOVA works with unequal group sizes; normality, equal variances and independence are the assumptions.")
Q("L16", "The technique of analysis of variance was developed by:", ["R. A. Fisher", "Karl Pearson", "W. S. Gosset", "Francis Galton"], "Fisher developed ANOVA for agricultural experiments at Rothamsted.")
Q("L16", "With only two groups, a one-way ANOVA gives F = 9. The equivalent two-sample t statistic has absolute value:", ["@", "9", "81", "4.5"], "F = t², so |t| = √9 = 3.", fmt(math.sqrt(9)))
Q("L16", "The error sum of squares is 48 with 12 degrees of freedom. The error mean square is:", ["@", "48", "36", "0.25"], "MSE = 48/12 = 4.", 48 // 12)
Q("L16", "In a one-way ANOVA, TSS = 150 and the treatment SS = 60. The error SS is:", ["@", "210", "2.5", "60"], "TSS = SST + SSE → SSE = 150 − 60 = 90.", 150 - 60)
Q("L16", "Data from a randomised block design are analysed by:", ["two-way classification ANOVA", "one-way classification ANOVA", "a χ² test of independence", "a paired t test only"], "Treatments and blocks are the two factors.")
Q("L16", "Data from a completely randomised design are analysed by:", ["one-way classification ANOVA", "two-way classification ANOVA", "a Latin square analysis", "regression on time"], "There is a single factor (treatments) plus error.")
Q("L16", "In an ANOVA, the calculated F is smaller than the table value. The conclusion is:", ["the treatment means do not differ significantly", "all treatment means are exactly equal", "the treatments differ significantly", "the variances are unequal"], "Not significant: the data are consistent with equal means.")
Q("L16", "MST = 12 with 3 df and MSE = 4 with 16 df. The F statistic and its degrees of freedom are:", ["3 with (3, 16)", "3 with (16, 3)", "0.33 with (3, 16)", "8 with (3, 16)"], "F = MST/MSE = 3, with (treatment df, error df) = (3, 16).")
assert F(12, 4) == 3
Q("L16", "In one-way ANOVA, which quantities always add up exactly?", ["Sums of squares and degrees of freedom", "Mean squares", "F ratios", "Mean squares and F ratios"], "TSS = SST + SSE and N − 1 = (k − 1) + (N − k); mean squares do not add.")

# ---------- L17 time series ----------
Q("L17", "The steady growth of a country’s population over several decades is an example of:", ["secular trend", "seasonal variation", "cyclical variation", "irregular variation"], "A long-term, smooth movement is the trend.", hy=True)
Q("L17", "Alternating periods of boom and depression in business activity over several years are:", ["cyclical variations", "seasonal variations", "secular trend", "irregular variations"], "Wave-like movements lasting more than a year are cyclical (the business cycle).")
Q("L17", "A sudden fall in production because of a flood is an example of:", ["irregular variation", "cyclical variation", "seasonal variation", "secular trend"], "Unpredictable, one-off events cause irregular (random) variation.")
Q("L17", "Higher sales of sweets every year during Diwali are an example of:", ["seasonal variation", "cyclical variation", "secular trend", "irregular variation"], "A pattern that repeats at the same time each year is seasonal.")
Q("L17", "The multiplicative model of a time series is:", ["Y = T × S × C × I", "Y = T + S + C + I", "Y = T × S + C × I", "Y = (T + S)(C + I)"], "Components multiply; the additive model adds them.")
Q("L17", "Under the additive model, the seasonal effects for the four quarters add up to:", ["0", "400", "100", "4"], "Additive seasonal effects are deviations, so they sum to zero.")
Q("L17", "Under the multiplicative model, quarterly seasonal indices (in %) should add up to:", ["400", "100", "1200", "0"], "Four indices averaging 100 add up to 400 (twelve monthly indices add up to 1200).", hy=True)
Q("L17", "The first 3-yearly moving average of 15, 18, 24, 27, 30 is:", ["@", "18", "21", "22.8"], "(15 + 18 + 24)/3 = 19, placed against the 2nd year.", fmt(mov_avg([15, 18, 24, 27, 30], 3)[0]))
Q("L17", "For the values 10, 12, 14, 16, 18, the first centred 4-yearly moving average is:", ["@", "13", "15", "12"], "4-year averages 13 and 15; centred: (13 + 15)/2 = 14.", fmt(centred([10, 12, 14, 16, 18], 4)[0]))
Q("L17", "A straight-line trend by least squares with years coded so that Σx = 0 gives n = 5, Σy = 150, Σxy = 40 and Σx² = 10. The trend equation is:", ["y = 30 + 4x", "y = 30 + 0.25x", "y = 150 + 4x", "y = 4 + 30x"], "a = Σy/n = 30; b = Σxy/Σx² = 4.", hy=True)
assert F(150, 5) == 30 and F(40, 10) == 4
Q("L17", "The trend is y = 30 + 4x with x = 0 at the middle year and x in years. The trend value 3 years after the middle year is:", ["@", "34", "12", "37"], "30 + 4 × 3 = 42.", 30 + 4 * 3)
Q("L17", "Six years are coded −5, −3, −1, 1, 3, 5 for a least-squares trend. One unit of x then equals:", ["half a year", "one year", "two years", "one quarter"], "Successive years differ by 2 units, so one unit is half a year.")
Q("L17", "By semi-averages, 6 years’ data 10, 12, 14, 18, 20, 22 give half-averages 12 and 20. The average annual increase in the trend is:", ["@", "8", "4", "1.33"], "The two averages are 3 years apart: (20 − 12)/3 = 2.67 per year.", fmt(F(20 - 12, 3)))
Q("L17", "Actual sales in a quarter are 220 and its seasonal index is 110. The deseasonalised sales are:", ["@", "242", "110", "330"], "220/110 × 100 = 200.", fmt(F(220 * 100, 110)))
Q("L17", "Quarterly seasonal indices total 396. A quarter with index 99 has an adjusted index of:", ["@", "99", "98.01", "396"], "99 × 400/396 = 100.", fmt(F(99 * 400, 396)))
Q("L17", "The ratio-to-moving-average method is used to measure:", ["seasonal variation", "secular trend only", "irregular variation only", "correlation between two series"], "Y divided by a centred moving average isolates S (with I), giving seasonal indices.")
Q("L17", "The link relative method of measuring seasonal variation is associated with:", ["Karl Pearson", "R. A. Fisher", "Irving Fisher", "Laspeyres"], "Pearson’s method chains the link relatives of successive seasons.")
Q("L17", "Data show a regular cycle of 5 years. To remove it, the moving average should cover:", ["@", "3 years", "4 years", "10 years"], "The period of the moving average should equal the cycle length: 5 years.", "%d years" % 5)
Q("L17", "The four phases of a business cycle, in order, are:", ["prosperity, recession, depression, recovery", "recovery, depression, prosperity, recession", "depression, prosperity, recession, recovery", "recession, recovery, prosperity, depression"], "Boom turns down (recession) to the bottom (depression) and climbs back (recovery).")
Q("L17", "The trend is y = 50 + 3x with x = 0 in 2020 and x in years. The trend value for 2026 is:", ["@", "53", "71", "65"], "x = 6: 50 + 18 = 68.", 50 + 3 * (2026 - 2020))
Q("L17", "A drawback of the moving-average method of finding trend is that:", ["trend values are lost at the beginning and end of the series", "it cannot smooth out fluctuations", "it always needs an even period", "it needs a mathematical equation"], "A k-period average gives no value for the first and last (k − 1)/2 periods, so it cannot be used to forecast.")

# ---------- L18 index numbers ----------
_p0, _p1, _q0, _q1 = [5, 4], [6, 5], [10, 20], [12, 15]
Q("L18", "Prices p₀ = 5, 4 and p₁ = 6, 5 with base quantities q₀ = 10, 20. Laspeyres’ price index is:", ["@", fmt(paasche(_p0, _p1, _q1)), fmt(F(sum(_p1), sum(_p0)) * 100), "130"], "Σp₁q₀/Σp₀q₀ × 100 = (60 + 100)/(50 + 80) × 100 = 160/130 × 100 ≈ 123.08.", fmt(laspeyres(_p0, _p1, _q0)), hy=True)
Q("L18", "Prices p₀ = 5, 4 and p₁ = 6, 5 with current quantities q₁ = 12, 15. Paasche’s price index is:", ["@", fmt(laspeyres(_p0, _p1, _q0)), "120", "147"], "Σp₁q₁/Σp₀q₁ × 100 = (72 + 75)/(60 + 60) × 100 = 147/120 × 100 = 122.5.", fmt(paasche(_p0, _p1, _q1)), hy=True)
Q("L18", "Laspeyres’ index is 144 and Paasche’s is 121. Fisher’s ideal index is:", ["@", "132.5", "265", "23"], "√(144 × 121) = 12 × 11 = 132.", fmt(math.sqrt(144 * 121)), hy=True)
Q("L18", "Laspeyres’ index is 120 and Paasche’s is 110. The Dorbish–Bowley index is:", ["@", "114.89", "230", "10"], "(120 + 110)/2 = 115. (114.89 is Fisher’s √(120 × 110).)", fmt(F(120 + 110, 2)))
assert fmt(math.sqrt(120 * 110)) == "114.89"
_p0, _p1, _q0, _q1 = [2, 4], [3, 5], [10, 5], [6, 9]
_me = F(sum(p * (a + b) for p, a, b in zip(_p1, _q0, _q1)), sum(p * (a + b) for p, a, b in zip(_p0, _q0, _q1))) * 100
Q("L18", "p₀ = 2, 4; p₁ = 3, 5; q₀ = 10, 5; q₁ = 6, 9. The Marshall–Edgeworth price index is:", ["@", "133.33", "125", fmt(laspeyres(_p0, _p1, _q0))], "Σp₁(q₀ + q₁)/Σp₀(q₀ + q₁) × 100 = (48 + 70)/(32 + 56) × 100 = 118/88 × 100 ≈ 134.09.", fmt(_me))
Q("L18", "Base-year prices of three items are 20, 30, 50 and current prices are 25, 36, 59. The simple aggregative price index is:", ["@", "100", "121.67", "125"], "Σp₁/Σp₀ × 100 = 120/100 × 100 = 120.", fmt(F(25 + 36 + 59, 20 + 30 + 50) * 100))
Q("L18", "Which of these satisfies the time reversal test?", ["Fisher’s index", "Laspeyres’ index", "Paasche’s index", "Dorbish–Bowley index"], "P₀₁ × P₁₀ = 1 holds for Fisher (and Marshall–Edgeworth), but not for Laspeyres, Paasche or their arithmetic mean.")
Q("L18", "The factor reversal test is satisfied by:", ["Fisher’s index only", "Laspeyres’ and Paasche’s indices", "Marshall–Edgeworth’s index", "every weighted aggregative index"], "Only Fisher’s ideal index gives P₀₁ × Q₀₁ = Σp₁q₁/Σp₀q₀.", hy=True)
Q("L18", "Which index satisfies the circular test?", ["Kelly’s fixed-weight aggregative index", "Fisher’s ideal index", "Laspeyres’ index", "Paasche’s index"], "With fixed weights (or the simple GM of relatives) the indices chain consistently; Fisher fails the circular test.")
Q("L18", "Which index fails the unit test?", ["Simple aggregative index", "Laspeyres’ index", "Fisher’s index", "Simple GM of price relatives"], "Σp₁/Σp₀ adds prices quoted in different units, so changing a unit changes the index.")
Q("L18", "An index number is 180 on the old base. The old index for the new base year is 120. On the new base, the index is:", ["@", "216", "60", "300"], "180/120 × 100 = 150.", fmt(F(180, 120) * 100))
Q("L18", "A worker earns ₹36,000 a month when the consumer price index is 160 (base = 100). The real wage in base-year rupees is:", ["@", "₹57,600", "₹36,160", "₹35,840"], "36000/160 × 100 = ₹22,500.", "₹{:,}".format(36000 * 100 // 160), hy=True)
Q("L18", "The consumer price index is 250. The purchasing power of a rupee (relative to the base year) is:", ["@", "₹2.50", "₹0.25", "₹4"], "100/250 = ₹0.40.", "₹" + fx(F(100, 250)))
Q("L18", "Link relatives for years 2 and 3 are 110 and 120 (year 1 = 100). The chain index for year 3 is:", ["@", "130", "120", "230"], "Year 2: 110; year 3: 110 × 120/100 = 132.", fmt(F(110 * 120, 100)))
Q("L18", "In the family budget method, two items have price relatives 150 and 120 and weights (values p₀q₀) 40 and 60. The cost of living index is:", ["@", "135", "270", "126"], "ΣIV/ΣV = (6000 + 7200)/100 = 132.", fmt(F(150 * 40 + 120 * 60, 100)))
Q("L18", "Laspeyres’ price index uses as weights the:", ["base-year quantities", "current-year quantities", "average of base and current quantities", "current-year prices"], "Σp₁q₀/Σp₀q₀ — q₀ in both sums.")
Q("L18", "Paasche’s price index uses as weights the:", ["current-year quantities", "base-year quantities", "base-year values", "geometric mean of q₀ and q₁"], "Σp₁q₁/Σp₀q₁ — q₁ in both sums.")
Q("L18", "Fisher’s index is called ‘ideal’ mainly because it:", ["satisfies both the time reversal and factor reversal tests", "uses current-year weights", "is the easiest to compute", "satisfies the circular test"], "It passes both reversal tests (though not the circular test).")
Q("L18", "An old index series (base 2010) stands at 160 in 2020. A new series has base 2020 = 100 and reads 115 in 2022. Spliced to the old base, the 2022 figure is:", ["@", "275", "71.88", "115"], "115 × 160/100 = 184.", fmt(F(115 * 160, 100)))
Q("L18", "Σp₀q₀ = 400 and Σp₁q₁ = 520. The value index is:", ["@", "76.92", "120", "92"], "Σp₁q₁/Σp₀q₀ × 100 = 130.", fmt(F(520, 400) * 100))
Q("L18", "Laspeyres’ quantity index is:", ["Σq₁p₀/Σq₀p₀ × 100", "Σq₁p₁/Σq₀p₁ × 100", "Σp₁q₀/Σp₀q₀ × 100", "Σq₁/Σq₀ × 100"], "Swap the roles of p and q: quantities change, base-year prices are the weights.")
Q("L18", "A firm’s sales rose to ₹500 crore when the price index stood at 125. Sales at base-year prices are:", ["@", "₹625 crore", "₹375 crore", "₹525 crore"], "500/125 × 100 = ₹400 crore.", "₹%s crore" % fmt(F(500 * 100, 125)))
